<?php use Hls\Http\View as V; ?><?php if($access->can('inventory.receipt.create')): ?><section class="panel"><form method="post" class="form-grid"><?= $this->csrf() ?><label>Tanggal<input type="date" name="receipt_date" value="<?= date('Y-m-d') ?>" required></label><label>Cabang<select name="branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><label>Gudang Tujuan<select name="warehouse_id" required><option value="">Pilih gudang</option><?php foreach($warehouses as $w): if($access->branch((int)$w["branch_id"])): ?><option value="<?= (int)$w["id"] ?>"><?= V::escape($w["code"]." - ".$w["name"]) ?></option><?php endif; endforeach ?></select></label><label>Supplier<select name="supplier_id"><option value="">Tanpa supplier</option><?php foreach($suppliers as $s): ?><option value="<?= (int)$s['id'] ?>"><?= V::escape($s['name']) ?></option><?php endforeach ?></select></label><label>Nomor transaksi<input name="receipt_ref" required></label><label>Referensi dokumen<input name="document_ref"></label><label>Keterangan<textarea name="note"></textarea></label><div data-receipt-items><div class="bill-item"><select name="item_id[]" required><option value="">Pilih barang</option><?php foreach($items as $i): ?><option value="<?= (int)$i['id'] ?>"><?= V::escape($i['code'].' - '.$i['name']) ?></option><?php endforeach ?></select><input name="quantity[]" type="number" min="0.001" step="0.001" placeholder="Kuantitas" required><button type="button" data-remove-item>Hapus</button></div></div><button type="button" data-add-item>+ Tambah Barang</button><button class="button button-primary">Simpan Draft</button></form></section><?php endif ?><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Tanggal</th><th>Cabang</th><th>Supplier</th><th>Jenis</th><th>Kuantitas</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['receipt_ref']) ?></td><td><?= V::escape($r['receipt_date']) ?></td><td><?= V::escape($r['branch_code']) ?></td><td><?= V::escape((string)$r['supplier_name']) ?></td><td><?= (int)$r['line_count'] ?></td><td><?= number_format((float)$r['total_qty'],3,',','.') ?></td><td><?= V::escape($r['status']) ?></td><td><a href="<?= $this->url('/inventory/receipt-detail?id='.(int)$r['id']) ?>">Detail</a></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="8" class="empty-state">Belum ada transaksi barang masuk.</td></tr><?php endif ?></tbody></table></div></section>
